using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models.Enums; using OCRS.Services;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class EnrollmentsController(ApplicationDbContext db,IRegistrationService registration):Controller { public async Task<IActionResult> Index(EnrollmentStatus? status){var q=db.Enrollments.Include(x=>x.Student).ThenInclude(x=>x.User).Include(x=>x.Class).ThenInclude(x=>x.Course).AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return View(await q.OrderByDescending(x=>x.RegisteredAt).ToListAsync());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Approve(int id){var e=await db.Enrollments.FindAsync(id);if(e?.Status==EnrollmentStatus.Pending){e.Status=EnrollmentStatus.Approved;e.ApprovedAt=DateTime.UtcNow;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Reject(int id){var e=await db.Enrollments.Include(x=>x.Student).SingleOrDefaultAsync(x=>x.EnrollmentId==id);if(e?.Status==EnrollmentStatus.Pending)await registration.CancelAsync(id,e.Student.UserId,true);return RedirectToAction(nameof(Index));} }
